          { name: "Bachelor of Education in Early Childhood Care and Education", aps: 28, duration: "4 years", description: "Prepares teachers for early childhood education, covering child development, early literacy and numeracy, and classroom practice. Graduates develop teaching young learners and creative lesson planning. Best suited to patient learners who love early education. Jobs: ECD Practitioner (R12 000–R35 000/month); Foundation Phase Teacher (R18 000–R45 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 } ] },
          { name: "Bachelor of Education in Foundation Phase Teaching (Grade R to Grade 3)", aps: 28, duration: "4 years", description: "Prepares teachers for Grades R–3, covering early literacy and numeracy, child development and classroom practice. Graduates develop teaching young learners and creative lesson planning. Best suited to patient learners who love early education. Jobs: Foundation Phase Teacher (R18 000–R45 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 } ] },
          { name: "Bachelor of Education in Intermediate Phase Teaching (Grades 4 to 6)", aps: 28, duration: "4 years", description: "Prepares teachers for Grades 4–6, covering subject knowledge, teaching methodology and classroom practice. Graduates develop teaching, assessment and classroom management. Best suited to learners who want to teach primary school. Jobs: Intermediate Phase Teacher (R18 000–R48 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 } ] },
          { name: "Bachelor of Education in Senior Phase and Further Education and Training Teaching (Grades 7 to 12)", aps: 28, duration: "4 years", description: "Prepares teachers for Grades 7–12 in two teaching subjects. Additional subject requirements for elective modules in Physical Sciences or Life Sciences: Physical Sciences and Mathematics passed with achievement level 5 (60–69%). Graduates develop subject expertise and classroom leadership. Best suited to learners who want to teach high-school subjects. Jobs: High School Teacher (R20 000–R52 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 } ] },
          { name: "Higher Certificate in Sports Sciences (1-year)", aps: 20, duration: "1 year", description: "An entry-level certificate in sports sciences, covering sports coaching, exercise science and sports management. Graduates develop sports coaching and exercise science skills. Best suited to learners who want a foundation in sports sciences. Jobs: Sports Coach (R12 000–R45 000/month); Sports Assistant (R10 000–R30 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 40 } ] },
          { name: "Higher Certificate in Sports Sciences (2-year online)", aps: 20, duration: "2 years", description: "An online certificate in sports sciences, covering sports coaching, exercise science and sports management. Students must have part-time access to schools, sports clubs or accredited training facilities. Graduates develop sports coaching and exercise science skills. Best suited to learners who want a flexible foundation in sports sciences. Jobs: Sports Coach (R12 000–R45 000/month); Sports Assistant (R10 000–R30 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 40 } ] }
